import { styled } from '@hexa-ui/theme';

export const StyledCreativeDevelopmentSection = styled('div', {
  width: '100%',
  minWidth: 0,

  '& [data-testid="sub-pillar-card"]': {
    width: '100%',
    maxWidth: 'none',
  },
});

export const StyledHowWeDoItImage = styled('img', {
  width: '100%',
  height: '166px',
  objectFit: 'contain',
});
